add_filter( 'woocommerce_checkout_fields', 'perfectpixel_disable_checkout_autocomplete', 9999 );

function perfectpixel_disable_checkout_autocomplete( $fields ) {
	// Field keys, e.g. billing_phone, billing_email, shipping_postcode.
	$fields_without_autocomplete = array( 'billing_phone' );

	foreach ( $fields as $group => $group_fields ) {
		foreach ( $group_fields as $key => $field ) {
			if ( in_array( $key, $fields_without_autocomplete, true ) ) {
				$fields[ $group ][ $key ]['autocomplete'] = 'off';
			}
		}
	}

	return $fields;
}
